tests.knapsack_01:
for(int tt=0;tt<150;tt++){
    int n=8,m=rng()%15;vector<pair<int,ll>>a;
    for(int i=0;i<n;i++)a.push_back({rng()%7,(int)(rng()%21)-10});
    ll best=0;
    for(int mask=0;mask<(1<<n);mask++){
        int w=0;ll v=0;for(int i=0;i<n;i++)if(mask>>i&1){w+=a[i].first;v+=a[i].second;}
        if(w<=m)best=max(best,v);
    }
    fill(dp,dp+m+1,0);for(auto [t,v]:a)add_item(m,t,(int)v);assert(dp[m]==best);
}

tests.complete_knapsack:
for(int tt=0;tt<100;tt++){
    n=rng()%20;pri.clear();for(int x=1;x<=7;x++)if(rng()%2)pri.push_back(x);
    function<ll(int,int)>brute=[&](int i,int cap){
        if(i==(int)pri.size())return cap==0?1LL:0LL;ll ways=0;
        for(int k=0;k*pri[i]<=cap;k++)ways+=brute(i+1,cap-k*pri[i]);return ways;
    };
    knapsack();assert(dp[n]==brute(0,n));
}
n=0;pri={2,3};knapsack();assert(dp[0]==1);
n=5;pri={2,3};knapsack();assert(dp[n]==1);

tests.group_knapsack:
for(int tt=0;tt<100;tt++){
    int m=rng()%15;
    for(int i=1;i<=4;i++){wp[i].clear();for(int j=0;j<3;j++)wp[i].push_back({(int)(rng()%6)+1,(int)(rng()%16)-5});}
    function<ll(int,int)>brute=[&](int i,int cap){
        if(i==5)return 0LL;ll ans=brute(i+1,cap);
        for(auto c:wp[i])if(c.a<=cap)ans=max(ans,c.b+brute(i+1,cap-c.a));return ans;
    };
    assert(knapsack(m,4)==brute(1,m));
}
for(int i=1;i<=4;i++)wp[i].clear();assert(knapsack(10,4)==0);

tests.convex_hull:
auto joined=[](const vector<Point>& p){
    auto [hi,lo]=getHull(p);vector<Point>h;
    auto append=[&](Point q){if(h.empty()||h.back().x!=q.x||h.back().y!=q.y)h.push_back(q);};
    for(auto q:lo)append(q);for(int i=(int)hi.size()-1;i>=0;i--)append(hi[i]);
    if(h.size()>1&&h.front().x==h.back().x&&h.front().y==h.back().y)h.pop_back();return h;
};
assert(joined({}).empty());assert(joined({{1,1},{1,1}}).size()==1);
assert(joined({{0,0},{1,1},{2,2},{1,1}}).size()==2);
assert(joined({{0,3},{0,1},{0,2},{0,1}}).size()==2);
for(int tt=0;tt<200;tt++){
    vector<Point>p;for(int i=0;i<30;i++)p.push_back({(int)(rng()%21)-10,(int)(rng()%21)-10});
    auto [hi,lo]=getHull(p);
    for(auto chain:{hi,lo})for(int i=1;i<(int)chain.size();i++)assert(chain[i-1].x<chain[i].x);
    auto h=joined(p);assert(h.size()>=3);
    for(int i=0;i<(int)h.size();i++){
        Point a=h[i],b=h[(i+1)%h.size()],c=h[(i+2)%h.size()];assert(cross(b-a,c-b)>0);
        for(auto q:p)assert(cross(b-a,q-a)>=0);
    }
}
